  const response = await fetch(base, { headers: { Cookie: cookie, 'x-region': region } })
  assert.equal(response.status, 200)
  const html = await response.text()
  for (const text of ['Workspace', 'Projects', '12 active projects', '4 archived projects', 'Your workspace', 'Loading your workspace details...', "'`Welcome, ${member}`, `Team: ${team}`, `Region: ${region}`]) {
    assert.ok(html.includes(text), `Expected ${JSON.stringify(text)} for ${member}`)
  }
  assert.ok(!html.includes(`Welcome, ${other}`), `Leaked ${other} details to ${member}`)
  console.log(`${member}: shared totals, streaming fallback, and private details verified`)
}
